def mark_cases_unsupported(testCase, caseNames, why):
    """Mark LATER cases UNSUPPORTED before they run, from the case that has just learned why.

    A case that finds out inside its own main() that it does not apply costs a power cycle of
    every device on the bench: the framework re-arms powerCycleOnFail before each case and
    cycles on any result but PASS. The TestSet runs a case only while its `supported` is True,
    so a case marked here is not run at all - no configure, main or tear_down, no cycle - and
    its class's `skipIfExcl = True` does the same under -u. Each marked case keeps its own check
    in main() for a run where this case did not run first (--include-test-cases, run-priority
    sampling). Module-level on purpose: the frame's lint reads every `self.testSet.<name>` as a
    device handle init() must bind.
    """
    wanted = set(caseNames)
    for tc in testCase.testSet.testCaseList:
        name = type(tc).__name__
        if name in wanted and tc.supported and not getattr(tc, 'hasBeenRun', False):
            tc.supported = False
            testCase.log('INFO: {} marked unsupported before it runs: {}'.format(name, why))


def publish_value(testCase, name, value):
    """Publish a value a later case reads: `testCase.testSet.<name> = value`.

    `None` means this case could not establish it, so every later case whose class lists
    `name` in its `ckNeeds` cannot run either: those are marked UNSUPPORTED before they run.
    """
    setattr(testCase.testSet, name, value)
    if value is None:
        mark_cases_unsupported(
            testCase, [type(tc).__name__ for tc in testCase.testSet.testCaseList
                       if name in getattr(type(tc), 'ckNeeds', ())],
            '{} was not established by {}'.format(name, type(testCase).__name__))


