CK_OFP_TCP_PORT = 6653
CK_PRIORITY = 100
CK_COOKIE_TAG = 0x4433          # cookie = (CK_COOKIE_TAG << 16) | generation
CK_APPFILE = '/tmp/ck44333_ctrl_app.py'
CK_FLOWFILE = '/tmp/ck44333_flows.json'
CK_RYULOG = '/tmp/ck44333_ryu.log'
CK_RYU_PGREP = '"[r]yu-manager .*ck44333_ctrl_app"'
CK_BLOCK_RULES = ('INPUT -p tcp --dport {} -j DROP'.format(CK_OFP_TCP_PORT),
                  'OUTPUT -p tcp --sport {} -j DROP'.format(CK_OFP_TCP_PORT))
# AlliedWare Plus fail-mode keyword is 'openflow failmode'; the option keyword is probed once
# (first accepted form wins) and then used everywhere.
CK_NRE_KEYWORDS = ('non-rule-expired', 'non-rule-expiry')
CK_STANDALONE_KEYWORDS = ('standalone', 'normal')
CK_SYNTAX_ERRORS = ('Invalid input', 'Unrecognized command', 'Incomplete command', 'Ambiguous command')

# Flow identities: (eth_src, eth_dst). F forward, D drop, T1/T2 timed, P permanent,
# N the entry added in step 10, T3 a further timed entry (step 15), U matches nothing.
CK_MAC = {
    'F': ('00:00:aa:00:00:01', '00:00:bb:00:00:01'),
    'D': ('00:00:aa:00:00:02', '00:00:bb:00:00:02'),
    'T1': ('00:00:aa:00:00:03', '00:00:bb:00:00:03'),
    'T2': ('00:00:aa:00:00:04', '00:00:bb:00:00:04'),
    'P': ('00:00:aa:00:00:05', '00:00:bb:00:00:05'),
    'N': ('00:00:aa:00:00:06', '00:00:bb:00:00:06'),
    'T3': ('00:00:aa:00:00:07', '00:00:bb:00:00:07'),
    'U': ('00:00:aa:00:07:01', '00:00:bb:00:07:99'),
}

