class TestCase_11(ATTestCase.TestCase):
    testCaseDesc = "Restore the controller connection and let the controller resynchronise its flow state. Read 'show openflow flows' on the DUT. Send flows F and N and capture on every egress data port."
    testCaseRef = 'AWPTCM-T44333, 9003.44333.11'
    ckNeeds = ['intendedFlows', 'baselineFlows']
    skipIfExcl = True
    testCaseMethod = testCaseDesc + '\n'
    testCaseMethod += 'Verify: The controller reconnects. The DUT flow table contains exactly the entries in intendedFlows (from step 10): the modified entry carries the new action, the added entry is present, and the removed entry is absent. No match appears more than once (no duplicates), and no entry outside intendedFlows remains (no orphans). Flow F egresses on the new port and flow N follows its new entry.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        pass

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 1023-1043
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 11: Restore the controller connection, let the controller resynchronise, read 'show openflow flows', send flows F and N.")
        for name in self.ckNeeds:
            if getattr(self.testSet, name, None) is None:
                self.supported = False
                self.failed('{} was not established by TestCase_10'.format(name))
                return
        intended = self.testSet.intendedFlows
        baseline = self.testSet.baselineFlows
        # Entries present in the baseline whose match is no longer in intendedFlows were removed by the controller
        intended_matches = [f.get('match') for f in intended]
        removed = [f for f in baseline if f.get('match') not in intended_matches]
        gen = self.testSet.flowGen
        ck_unblock(self.testSet)
        connected, elapsed, block, status = ck_wait_controller(self.testSet, True, 120)
        if connected:
            self.passed('Controller oc1 reconnected after {:.0f}s'.format(elapsed))
        else:
            self.failed('Controller oc1 did not reconnect: {}'.format(' | '.join(block)[:120]))
            return
        done, text, entries, probs = ck_wait_table(self, intended, 30, gen)
        self.log('OBSERVED: {}'.format(text))
        ours = ck_ours(entries)
        keys = [(e['src'], e['dst']) for e in ours]
        dups = sorted(set(k for k in keys if keys.count(k) > 1))
        if dups:
            self.failed('Duplicate matches in the flow table: {}'.format(dups))
        else:
            self.passed('No duplicate match among {} flow entries'.format(len(ours)))
        for f in intended:
            p = ck_flow_problems(ours, f, gen)
            if p:
                self.failed('Intended entry {}: {}'.format(f['name'], '; '.join(p)))
            else:
                self.passed('Intended entry {} present with actions {} and timeouts {}/{}'.format(
                    f['name'], f['actions'], f['idle_timeout'], f['hard_timeout']))
        for f in removed:
            fmatch = f.get('match') or {}
            fname = f.get('name', fmatch)
            hits = [e['raw'] for e in entries
                    if e['src'] == fmatch.get('eth_src') and e['dst'] == fmatch.get('eth_dst')]
            if hits:
                self.failed('Removed entry {} still present: {}'.format(fname, hits))
            else:
                self.passed('Removed entry {} is absent from the flow table'.format(fname))
        orphans = [p for p in ck_compare(entries, intended, gen) if p.startswith('orphan')]
        if orphans:
            self.failed('Orphan entries outside intendedFlows remain: {}'.format(orphans))
        elif len(ours) == len(intended):
            self.passed('No orphan entries; flow table holds exactly the {} intended entries'.format(len(intended)))
        else:
            self.failed('Flow table holds {} entries, intendedFlows has {}'.format(len(ours), len(intended)))

        numPkts = 10
        counts = ck_traffic(self, ['F', 'N'], [tb.ethB, tb.ethC], numPkts)
        for name in ('F', 'N'):
            f = ck_find(intended, name)
            iface = ck_iface_of_port(self.testSet, f['egress'])
            rx = counts[iface][name]
            other = sum(c[name] for i, c in counts.items() if i != iface)
            if rx == numPkts and other == 0:
                self.passed('Flow {} follows its entry: {} of {} on {}, none elsewhere'.format(name, rx, numPkts, f['egress']))
            else:
                self.failed('Flow {} received {} on {} and {} elsewhere, expected {} on {} only'.format(
                    name, rx, f['egress'], other, numPkts, f['egress']))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        ck_unblock(self.testSet)
        dutA.mode('#')


class TestCase_12(ATTestCase.TestCase):
    testCaseDesc = "With the non-rule-expiry option enabled and the populated flow table from step 11, run at least 10 interrupt/restore cycles using the step 5 method. Vary the interruption length, and make several interruptions shorter than the controller reconnection interval (read the interval from the controller/OpenFlow status or configuration). After each cycle, read 'show openflow flows' and 'show openflow status'."
    testCaseRef = 'AWPTCM-T44333, 9003.44333.12'
    ckNeeds = ['intendedFlows']
    skipIfExcl = True
    testCaseMethod = testCaseDesc + '\n'
    testCaseMethod += "Verify: After every cycle the flow entry count equals the count in intendedFlows (from step 10), and every entry's match, actions and timeouts are unchanged. The count never drops from one cycle to the next. The controller is reported connected again after each restore.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # The controller connection starts restored (step 11).
        ck_unblock(self.testSet)

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 995-1003
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log('STEP 12: Run at least 10 interrupt/restore cycles (step-5 method) of varied length, several shorter than the reconnection interval.')
        intended = self.testSet.intendedFlows
        if intended is None:
            self.supported = False
            self.failed('intendedFlows was not established by TestCase_10')
            return
        if not ck_wait_controller(self.testSet, True, 120)[0]:
            self.failed('controller oc1 is not connected before the cycles')
            return
        if not ck_wait_table(self, intended, 10)[0]:
            gen = ck_push_flows(self, intended)
            done, text, entries, probs = ck_wait_table(self, intended, 30, gen)
            if not done:
                self.failed('Flow table does not hold intendedFlows before the cycles: {}'.format('; '.join(probs[:4])))
                return
        dutA.mode('#')
        status = dutA.cmd('show openflow status')
        run = dutA.cmd('show running-config | include openflow')
        interval, source = ck_reconnect_interval(status + '\n' + run)
        if interval is None:
            interval = 8.0
            self.log('Reconnection interval not reported by the DUT; using the OpenFlow default maximum backoff 8 s')
        else:
            self.log('Reconnection interval {} s from: {}'.format(interval, source))
        factors = [0.25, 0.5, 1.5, 0.75, 0.25, 2.5, 0.5, 3.0, 0.75, 0.4, 1.2, 0.6]
        lengths = [max(0.5, round(interval * f, 1)) for f in factors]
        short = [x for x in lengths if x < interval]
        self.log('Disconnected periods (s): {}; {} shorter than the {} s reconnection interval'.format(lengths, len(short), interval))

        detectFail, heldProblems, afterProblems, reconnectFail, drops = [], [], [], [], []
        prev = len(intended)
        cycles = 0
        lastText = ''
        for idx, length in enumerate(lengths, 1):
            ck_block(self.testSet)
            disc, dt, _, _ = ck_wait_controller(self.testSet, False, 90)
            if not disc:
                detectFail.append(idx)
            text, entries = ck_read_flows(self)
            probs = ck_compare(entries, intended)
            if probs:
                heldProblems.append('cycle {}: {}'.format(idx, '; '.join(probs[:3])))
            duringCount = len(ck_ours(entries))
            time.sleep(length)
            ck_unblock(self.testSet)
            conn, ct, _, _ = ck_wait_controller(self.testSet, True, 90)
            if not conn:
                reconnectFail.append(idx)
            ok, lastText, entries, probs = ck_wait_table(self, intended, 20)
            if probs:
                afterProblems.append('cycle {}: {}'.format(idx, '; '.join(probs[:3])))
            afterCount = len(ck_ours(entries))
            for count in (duringCount, afterCount):
                if count < prev:
                    drops.append('cycle {}: {} -> {}'.format(idx, prev, count))
                prev = count
            cycles += 1
            self.log('Cycle {}: detect {:.0f}s, disconnected {}s, reconnect {:.0f}s, entries during {} after {}'.format(
                idx, dt, length, ct, duringCount, afterCount))
        self.log('OBSERVED: {}'.format(lastText))
        if cycles >= 10:
            self.passed('{} interrupt/restore cycles completed'.format(cycles))
        else:
            self.failed('Only {} cycles completed, need at least 10'.format(cycles))
        if len(short) >= 3:
            self.passed('{} interruptions were shorter than the {} s reconnection interval'.format(len(short), interval))
        else:
            self.failed('Only {} interruptions were shorter than the reconnection interval'.format(len(short)))
        if not detectFail:
            self.passed('Every interruption was detected (controller oc1 reported not connected)')
        else:
            self.failed('Interruption not detected in cycles {}'.format(detectFail))
        if not heldProblems:
            self.passed('During every interruption the table equalled intendedFlows ({} entries)'.format(len(intended)))
        else:
            self.failed('Table changed during interruptions: {}'.format(' | '.join(heldProblems[:4])))
        if not afterProblems:
            self.passed('After every cycle the table equalled intendedFlows, entries unchanged')
        else:
            self.failed('Table differed from intendedFlows after cycles: {}'.format(' | '.join(afterProblems[:4])))
        if not drops:
            self.passed('The entry count never dropped across the cycles')
        else:
            self.failed('Entry count dropped: {}'.format('; '.join(drops[:5])))
        if not reconnectFail:
            self.passed('Controller oc1 was reported connected again after every restore')
        else:
            self.failed('Controller oc1 did not reconnect after cycles {}'.format(reconnectFail))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        ck_unblock(self.testSet)
        dutA.mode('#')


class TestCase_13(ATTestCase.TestCase):
    testCaseDesc = 'With the fail mode set to secure and the non-rule-expiry option enabled, try to change the fail mode to standalone while the option is still set.'
    testCaseRef = 'AWPTCM-T44333, 9003.44333.13'
    testCaseMethod = testCaseDesc + '\n'
    testCaseMethod += "Verify: The DUT rejects the command and prints a clear '%' error indication. 'show openflow status' and running-config still show the secure fail mode with the non-rule-expiry option enabled, and the controller stays connected.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        ck_unblock(self.testSet)
        ck_cfg(self.testSet, ck_suite_failmode_cmd(self.testSet))

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 995-1003
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log('STEP 13: With secure fail mode and non-rule-expiry enabled, try to change the fail mode to standalone.')
        dutA.mode('#')
        before = dutA.cmd('show running-config | include openflow')
        fmBefore = ck_runcfg_failmode(before)
        if not any('secure' in line and ck_nre_in(line) for line in fmBefore):
            self.supported = False
            self.failed('{} could not be put in secure fail mode with non-rule-expiry: {}'.format(dutA.name, fmBefore))
            return
        ck_wait_controller(self.testSet, True, 60)
        kw, out = ck_try_standalone(self)
        dutA.mode('#')
        status = dutA.cmd('show openflow status')
        running = dutA.cmd('show running-config | include openflow')
        fm = ck_runcfg_failmode(running)
        state, block, _ = ck_controller(self.testSet)
        self.log('OBSERVED: command "{}" output: {} | failmode config: {} | status: {}'.format(
            kw, out.strip(), fm, status))
        if kw is None:
            self.failed('None of {} is accepted by the CLI parser as a fail mode: {}'.format(
                list(CK_STANDALONE_KEYWORDS), out.strip()[:100]))
        elif '%' in out:
            self.passed("Change to {} was rejected with a '%' error: {}".format(kw, out.strip()[:100]))
        else:
            self.failed("Change to {} was accepted, expected a '%' rejection: {}".format(kw, out.strip()[:100]))
        mode, nre, flines = ck_status_failmode(status)
        if mode == 'secure' and nre is True:
            self.passed('show openflow status still shows secure with non-rule-expiry enabled: {}'.format(flines))
        else:
            self.failed('show openflow status fail mode {} non-rule-expiry {}: {}'.format(mode, nre, flines))
        if any('secure' in line and ck_nre_in(line) for line in fm):
            self.passed('running-config still shows secure fail mode with non-rule-expiry: {}'.format(fm))
        else:
            self.failed('running-config lost secure/non-rule-expiry: {}'.format(fm))
        if any(re.search(r'\b(standalone|normal)\b', line) for line in fm):
            self.failed('running-config shows a standalone fail mode after the rejected change: {}'.format(fm))
        else:
            self.passed('running-config does not contain a standalone fail mode')
        if state is True:
            self.passed('controller oc1 stays connected: {}'.format(' | '.join(block)[:120]))
        else:
            self.failed('controller oc1 is not reported connected: {}'.format(' | '.join(block)[:120]))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Restore the suite fail mode in case the change was accepted.
        ck_cfg(self.testSet, ck_suite_failmode_cmd(self.testSet))


