class TestCase_15(ATTestCase.TestCase):
    testCaseDesc = "From the controller, install timed entries again: a forward entry for flow F and a drop entry for flow D, each with idle and hard timeouts, plus one further timed entry. Confirm they are in 'show openflow flows'. Interrupt the controller connection by the step 5 method, then poll 'show openflow flows' for longer than the longest of these timeouts."
    testCaseRef = 'AWPTCM-T44333, 9003.44333.15'
    testCaseMethod = testCaseDesc + '\n'
    testCaseMethod += 'Verify: Each timed entry is present before its timeout elapses and is gone from the DUT flow table once its idle or hard timeout has elapsed (within a polling margin). This is the default expiry behaviour, now that the option has been removed.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Precondition: secure fail mode WITHOUT the non-rule-expiry option, controller connected.
        ck_unblock(self.testSet)
        ck_cfg(self.testSet, 'openflow failmode secure')

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 79-85
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 15: Install timed F, D and T3 from the controller, confirm them, interrupt the controller connection and poll 'show openflow flows' past the longest timeout.")
        if not ck_wait_controller(self.testSet, True, 120)[0]:
            self.failed('controller oc1 is not connected, the timed entries cannot be installed')
            return
        nums, status = ck_of_ports(self.testSet)
        B = nums.get(dutA.portB.name)
        C = nums.get(dutA.portC.name)
        if B is None or C is None:
            self.failed('No OpenFlow port number for {}/{}: {}'.format(dutA.portB.name, dutA.portC.name, status.strip()[:120]))
            return
        flows = [ck_flow('F', B, dutA.portB.name, 30, 45),
                 ck_flow('D', None, None, 35, 40),
                 ck_flow('T3', C, dutA.portC.name, 0, 50)]
        gen = ck_push_flows(self, flows)
        installT = self.testSet.lastInstallTime
        done, text, entries, probs = ck_wait_table(self, flows, 20, gen)
        self.log(text)
        if not done:
            self.failed('Timed entries not installed as sent: {}'.format('; '.join(probs[:4])))
            return
        self.passed('{} timed entries present in show openflow flows before their timeouts'.format(len(flows)))
        ck_block(self.testSet)
        margin = 10
        expiries = dict((f['name'], ck_expiry(f)) for f in flows)
        end = max(expiries.values()) + margin + 4
        polls = []
        while True:
            t = time.time() - installT
            text, entries = ck_read_flows(self)
            present = set(f['name'] for f in flows if ck_entry(entries, f) is not None)
            state = ck_controller(self.testSet)[0]
            polls.append((t, present, state))
            if t >= end:
                break
            time.sleep(2)
        self.log('OBSERVED: {}'.format('; '.join('{:.0f}s:{}{}'.format(
            t, sorted(p), '' if s else '(oc1 down)') for t, p, s in polls)))
        if any(s is False for t, p, s in polls):
            self.passed('The controller connection was interrupted during the polling window')
        else:
            self.failed('controller oc1 was never reported disconnected during the polling window')
        for f in flows:
            e = expiries[f['name']]
            before = [p for p in polls if p[0] < e - 2]
            after = [p for p in polls if p[0] > e + margin]
            if before and all(f['name'] in p[1] for p in before):
                self.passed('Entry {} present at all {} polls before its {}s timeout'.format(f['name'], len(before), e))
            else:
                self.failed('Entry {} missing before its {}s timeout (polls {})'.format(
                    f['name'], e, [(int(p[0]), f['name'] in p[1]) for p in before]))
            if after and all(f['name'] not in p[1] for p in after):
                self.passed('Entry {} gone at all {} polls after its {}s timeout + {}s margin'.format(f['name'], len(after), e, margin))
            else:
                self.failed('Entry {} still present after its {}s timeout + {}s margin (polls {})'.format(
                    f['name'], e, margin, [(int(p[0]), f['name'] in p[1]) for p in after]))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        ck_unblock(self.testSet)
        ck_cfg(self.testSet, ck_suite_failmode_cmd(self.testSet))


class TestCase_16(ATTestCase.TestCase):
    testCaseDesc = "Restore the controller connection. Install the flow F forward entry and the flow D drop entry again, with timeouts shorter than the planned interruption, and record each entry's install time. Interrupt the controller connection. Send flows F and D before their timeouts elapse and again after they elapse, capturing on every egress data port. Then restore the connection."
    testCaseRef = 'AWPTCM-T44333, 9003.44333.16'
    testCaseMethod = testCaseDesc + '\n'
    testCaseMethod += 'Verify: Before the timeouts elapse, flow F is forwarded and flow D is dropped. Once the timeouts have elapsed, the entries are absent from the DUT flow table, and flow F is no longer received on any egress data port: it is handled as unmatched traffic under the secure fail mode. The controller reconnects after the restore.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Precondition: secure fail mode without the option (default expiry).
        ck_cfg(self.testSet, 'openflow failmode secure')

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 995-1003
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log('STEP 16: Restore the controller connection, install timed F and D, interrupt, send F and D before and after their timeouts, then restore.')
        ck_unblock(self.testSet)
        if not ck_wait_controller(self.testSet, True, 120)[0]:
            self.failed('controller oc1 did not connect before the flows were installed')
            return
        nums, status = ck_of_ports(self.testSet)
        B = nums.get(dutA.portB.name)
        if B is None:
            self.failed('No OpenFlow port number for {}'.format(dutA.portB.name))
            return
        timeout = 45
        flows = [ck_flow('F', B, dutA.portB.name, 40, timeout), ck_flow('D', None, None, 40, timeout)]
        gen = ck_push_flows(self, flows)
        installT = self.testSet.lastInstallTime
        done, text, entries, probs = ck_wait_table(self, flows, 20, gen)
        self.log('Installed at {:.0f}: {}'.format(installT, text))
        if not done:
            self.failed('F and D not installed as sent: {}'.format('; '.join(probs[:4])))
            return
        ck_block(self.testSet)
        down = ck_wait_controller(self.testSet, False, max(5, 30 - (time.time() - installT)))[0]
        numPkts = 10
        tBefore = time.time() - installT
        before = ck_traffic(self, ['F', 'D'], [tb.ethB, tb.ethC], numPkts)
        self.log(ck_read_flows(self)[0])
        remaining = timeout + 10 - (time.time() - installT)
        if remaining > 0:
            time.sleep(remaining)
        textAfter, entriesAfter = ck_read_flows(self, log=True)
        after = ck_traffic(self, ['F', 'D'], [tb.ethB, tb.ethC], numPkts)
        ck_unblock(self.testSet)
        reconnected = ck_wait_controller(self.testSet, True, 120)[0]
        self.log('OBSERVED: down={} before(t={:.0f}s)={} after={} reconnected={}\n{}'.format(
            down, tBefore, before, after, reconnected, textAfter))

        if down:
            self.passed('controller oc1 reported disconnected during the interruption')
        else:
            self.failed('controller oc1 was not reported disconnected before the first burst')
        if tBefore >= timeout - 5:
            self.failed('The before-timeout burst was sent {:.0f}s after install, too close to the {}s timeout'.format(tBefore, timeout))
        bF = before[tb.ethB.name]['F']
        if bF == numPkts and before[tb.ethC.name]['F'] == 0:
            self.passed('Flow F forwarded on {} before the timeout ({} of {})'.format(dutA.portB.name, bF, numPkts))
        else:
            self.failed('Flow F before the timeout: {} on {}, {} elsewhere, expected {}'.format(
                bF, dutA.portB.name, before[tb.ethC.name]['F'], numPkts))
        bD = sum(c['D'] for c in before.values())
        if bD == 0:
            self.passed('Flow D dropped before the timeout (0 received)')
        else:
            self.failed('Flow D received {} before the timeout, expected 0'.format(bD))
        left = [e['raw'] for f in flows for e in entriesAfter
                if e['src'] == f['match']['eth_src'] and e['dst'] == f['match']['eth_dst']]
        if not left:
            self.passed('F and D entries absent from the flow table after their timeouts')
        else:
            self.failed('Entries still present after their timeouts: {}'.format(left))
        aF = sum(c['F'] for c in after.values())
        if aF == 0:
            self.passed('Flow F received on no egress port after the timeout (unmatched, secure fail mode)')
        else:
            self.failed('Flow F still received {} after the timeout: {}'.format(aF, after))
        aD = sum(c['D'] for c in after.values())
        if aD == 0:
            self.passed('Flow D received on no egress port after the timeout')
        else:
            self.failed('Flow D received {} after the timeout: {}'.format(aD, after))
        if reconnected:
            self.passed('controller oc1 reconnected after the restore')
        else:
            self.failed('controller oc1 did not reconnect after the restore')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        ck_unblock(self.testSet)
        ck_cfg(self.testSet, ck_suite_failmode_cmd(self.testSet))


class TestCase_17(ATTestCase.TestCase):
    testCaseDesc = "Read 'show openflow status' and running-config in the default configuration (secure fail mode, non-rule-expiry option absent)."
    testCaseRef = 'AWPTCM-T44333, 9003.44333.17'
    testCaseMethod = testCaseDesc + '\n'
    testCaseMethod += 'Verify: The OpenFlow status reports the fail mode as secure and reports the non-rule-expiry option as not enabled. Running-config matches.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # The default fail-mode configuration.
        ck_cfg(self.testSet, 'no openflow failmode')

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 995-1003
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 17: Read 'show openflow status' and running-config in the default configuration.")
        dutA.mode('#')
        status = dutA.cmd('show openflow status')
        if ck_syntax_error(status):
            self.supported = False
            self.failed('{} does not support show openflow status: {}'.format(dutA.name, status.strip()[:80]))
            return
        running = dutA.cmd('show running-config | include openflow')
        self.log('OBSERVED: STATUS:\n{}\nRUNNING:\n{}'.format(status, running))
        mode, nre, flines = ck_status_failmode(status)
        if mode == 'secure':
            self.passed('show openflow status reports fail mode secure: {}'.format(flines))
        else:
            self.failed('show openflow status fail mode is {}, expected secure: {}'.format(mode, flines))
        if nre is not True:
            self.passed('show openflow status reports non-rule-expiry not enabled: {}'.format(flines))
        else:
            self.failed('show openflow status reports non-rule-expiry enabled: {}'.format(flines))
        fm = ck_runcfg_failmode(running)
        bad = [line for line in fm if re.search(r'\b(standalone|normal)\b', line) or ck_nre_in(line)]
        if bad:
            self.failed('running-config contains a non-default fail-mode setting: {}'.format(bad))
        elif fm and not all('secure' in line for line in fm):
            self.failed('running-config fail-mode lines are not secure: {}'.format(fm))
        else:
            self.passed('running-config shows the default secure fail mode with no non-rule-expiry option: {}'.format(fm or 'default'))
        if re.search(r'^\s*openflow controller oc1 tcp {}\b'.format(re.escape(self.testSet.ctrlIp)), running, re.M):
            self.passed('running-config keeps the openflow controller oc1 line')
        else:
            self.failed('running-config lost the openflow controller oc1 line: {}'.format(running.strip()[:120]))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        ck_cfg(self.testSet, ck_suite_failmode_cmd(self.testSet))


